import { curveCode, feedbackCode, feedbackSampleCode, pointerMouseCode, shaderInputCode, chromaticShader, audioCode, typographyCode, paletteCode, swarmCode, cameraFlightShots } from "./workshop-code.js";
import { workshopCatalog } from "./workshop-projects.js";

const editors = ["browser-editor", "app"];
const step = (title, text, extra = {}) => ({ title, text, ...extra });
const table = (headers, rows) => ({ headers, rows });
function lesson(id, title, summary, reference, steps, extra = {}) {
  const [, number] = workshopCatalog.find(row => row[0] === id);
  return { id, number, title, summary, level: "Workshop", environments: editors,
    startProject: `/online-editor/?example=workshop-${id}-start`,
    completedProject: `/online-editor/?example=workshop-${id}-complete`,
    startDownload: `/projects/tutorials/${id}/start.json`, download: `/projects/tutorials/${id}/complete.json`,
    previewProject: `workshop-${id}-complete`, referenceUrl: `/reference/#${reference}`, referenceLabel: "API Reference", steps, ...extra };
}

const curve = lesson("curve-motion", "同じ動きを、Curveで気持ちよくする", "位置も尺も同じ3つの円。補間だけを変えて、動きの印象を比べる。", "defineparams", [
  step("同じ条件の3つの円を用意する", "開始用は1280 × 720、60 fps、240フレーム。3つのClipのxには、0で230、119で1080、239で230という同じキーが入っています。最初はすべてLinearです。完成プレビューでは上からLinear、Sine In Out、Back Outを比較できます。まず再生し、速さの違いと到着前後の印象を見てください。", { checks: ["目安15〜20分。Inspectorでキーを付ける基本操作を知っていれば進められます。", "コードはxを描く位置へ使うだけです。3つのClipの時刻と値をそろえて比較します。"] }),
  step("Inspectorでxのキーを確認する", "TimelineでSINE IN OUTのClipを選び、Customのxを選択します。Frames表示にして0・119・239へシークし、値が230・1080・230であることを確認します。ここではキーを増やしません。位置を描くコードと、時間変化を決めるキーを分けて考えます。", { code: curveCode }),
  step("Curveで補間だけを変える", "Curveへ切り替え、xのカーブの0フレームのキーを選び、EasingをSine In Outにします。これは0→119の区間に作用します。119のキーにも同じ設定をすると、119→239の戻りも加減速します。最後の239には次の区間がないので、補間を変えてもこの尺内の動きは変わりません。", { checks: ["キーを選ぶだけではPlayheadは移動しません。見たい時刻はルーラーやTimeline positionから指定します。", "FrameとValueは変えず、まずEasingだけを変えてください。"] }),
  step("Linear・Sine・Backを比べる", "BACK OUTのClipでは0と119のEasingをBack Outへ変えます。到着点を少し越えて戻る動きになります。完成版はこの3種類です。同じ位置と尺でも、動き始め・止まり方・行き過ぎの有無で印象が変わります。", { table: table(["補間", "見える違い", "使いどころ"], [["Linear", "区間の中を等速で移動", "一定速度の走査や比較の基準"], ["Sine In Out", "ゆっくり始まり、ゆっくり止まる", "落ち着いた移動やUIの出入り"], ["Back Out", "終点を越えてから戻る", "弾力のある登場や強調"]]) }),
  step("Bezierで自分の止まり方をつくる", "1区間の始点キーを選び、Bezierへ切り替えてハンドルを動かします。横方向は区間内の時間、縦方向は値の変化です。終わり側を水平に近づけると、到着前の変化を小さくできます。完成版と比べ、変えすぎたらUndoで戻しましょう。Backのような行き過ぎは画面の外へ出ることもあるので、実際の描画も確認します。"),
  step("止めて比べ、保存する", "0・30・60・90・119へ順にシークします。3つの円は同じ時刻でも途中の位置が違い、0と119では同じ位置にそろいます。240はOutで含まれません。完成版を基準に、キーの時刻を動かす変更と補間を変える変更を別々に試し、File > Save Asで保存します。")
], { level: "Timeline / Curve" });

const pointer = lesson("feedback-pointer", "Feedbackで手の動きを録って再生する", "InspectorでPointerを割り当て、onMouseDown・Move・Upで記録した線を描く。", "feedback-mouse", [
  step("開始用と完成版の違いを確認する", "教材は1280 × 720、60 fps、8秒です。Inspectorで割り当てた記録をonMouseDown()・onMouseMove()・onMouseUp()で受け取ります。Hand Takeは、練習用に生成した2本のストロークです。実際に手で録ったデータではありません。開始用はPointerがNone、完成版はpointerを指定済みで、コードと記録データは共通です。まず完成プレビューを開き、Playで線とイベント数が増えることを確認してください。Feedbackは映像の残像ではなく、座標・ボタン状態・時刻のデータです。", { checks: ["目安20分。記録と割り当てはブラウザEditorまたはアプリ版で行います。", "Playerは保存済み記録を再生します。カードの静止画だけでなく、開いたプレビューのPlayで確認してください。"] }),
  step("自分のPointerを記録する", "開始用プロジェクトを開き、Playheadを0に戻してComposition上部のRecord Feedbackの設定でPointerを選び、Recordを開始します。記録中は1倍速の前進再生になり、ループしません。プレビュー内でボタンを押して線を描き、離してからもう1本描きます。Stop後のReviewでSaveを選び、Hand Take 2などの名前でProjectへ追加します。Discardはそのtakeを捨てます。プレビューのズームやパンを除いたComposition座標で記録されます。同梱データで設定だけ試す場合は、記録せず次へ進めます。"),
  step("InspectorでSourceとPointerを指定する", "TimelineのPointer Readerを選び、InspectorのFeedbackを開きます。SourceにHand Take、Pointerにpointer、SpaceにClipを指定します。自分で保存した場合はSourceをHand Take 2などの新しいアセットへ変えます。Timing and detailsはOffset 0、Rate 1、Loop OFFにしてApplyを押してください。Sourceだけを選び、PointerがNoneのままでは、アセット名を省略したonMouseコールバックは働きません。Apply後のStandard input readyを確認してから再生します。CustomのtakeNameを書き換える手順は不要です。", { table: table(["項目", "この教材の設定", "役割"], [["Source", "Hand Take（または自分の記録）", "受け取るFeedbackアセット"], ["Pointer", "pointer", "受け取るPointerチャンネル"], ["Space", "Clip", "記録の座標をClipのCanvasへ換算"], ["Offset / Rate / Loop", "0 / 1 / OFF", "記録の時間をそのまま再生"], ["Apply", "変更後に押す", "割り当てをClipへ保存"]]) }),
  step("3つのコールバックでイベントを受け取る", "onMouseDown(e => …)は押した記録、onMouseMove(e => …)は移動の記録、onMouseUp(e => …)は離した記録を受け取ります。次は確認用の短い例です。登録はClipのトップレベルかsetup()内で一度だけ行い、onFrame()内へは置きません。引数にアセット名を書かない形では、保存済みのInspector割り当てを使います。これは記録済みPointerの再生用で、画面上のライブマウスを監視する関数ではありません。同じフレームではコールバックの後にonFrame()が呼ばれるので、先に座標を蓄積し、その結果を描画できます。", { code: 'onMouseDown(e => {\n  console.log("down", e.x, e.y, e.buttons);\n});\nonMouseMove(e => {\n  console.log("move", e.px, e.py, e.x, e.y);\n});\nonMouseUp(e => {\n  console.log("up", e.canceled);\n});', table: table(["イベントの値", "意味"], [["x / y", "Spaceに応じた現在の座標"], ["px / py", "直前の記録イベントの座標（前の描画フレームとは別）"], ["buttons / button", "押されているボタンのビットマスク / 遷移したボタン"], ["time / frameTime", "Feedback内の秒数 / Clip内の秒数"], ["seq", "記録イベントの順序番号"], ["canceled", "本物のcancelをonMouseUpで受けたときtrue"]]) }),
  step("記録イベントから線を組み立てる", "Pointer Readerの完成コードです。Downで線を作り、押されているMoveで点を増やし、Upで線を終えます。bg()・lines()・oval()・text()はCentiの描画関数です。表示するdown・move・upは、実際に届いたコールバックの回数です。最初のtickは現在の状態を読むだけなので、記録の先頭からすでにボタンが押されている場合に備え、Moveでも線を始められるようにしています。その際はpx・pyを始点に使います。canceledのUpでは終点を追加せずに現在のストロークを終了します。", { code: pointerMouseCode }),
  step("Playとシークの違いを試す", "0からPlayするとイベントが1回ずつ届き、線とカウンターが増えます。Pause・フレームステップ・シークではコールバックを送らず、過去のイベントも再実行しません。そのため、途中へシークしただけで完成した軌跡が再構築されるわけではありません。このコードは時刻が戻ったときに蓄積した線を消します。サイトのプレビューではResetでClipを読み直し、Editorでは0へ戻ってから前進再生して確認してください。前方へシークしたときには以前の描画状態が残るため、毎回同じ線を比較するときは最初から再生します。", { checks: ["Play中はmoveなどの数が増える。Pause中は増えない。", "PointerをNoneにしてApplyすると、同じコードでも記録イベントは届かなくなる。", "ランダムな時刻でも同じ画像を描きたい場合は、別記事「Alternate：sample()とat()でFeedbackを描く」を参照。"] }),
  step("自分の記録に切り替えて保存する", "InspectorのSourceを自分で保存したFeedbackへ、Pointerをその記録のPointerチャンネルへ変えてApplyします。同じonMouseコードのまま、別の手の動きで描けます。描けないときはSourceとPointer、Apply済みか、前進再生中か、ClipのIn / Outを確認してください。Review中のtakeは先にSaveし、割り当てたあとFile > Save Asでプロジェクトを保存します。再度開いて、記録アセットとPointer割り当てが残っていることを確認します。イベントから蓄積した線は実行中の状態なので、保存後も再生して描き直します。"),
  step("名前で受け取る方式も知っておく", "onMouseDown(\"Hand Take\", callback)のようにProject上のアセット名を渡す別の方式もあります。その形ならInspectorでPointerを割り当てなくても、指定したFeedbackを使えます。Hand Takeでの例は次のとおりです。複数のPointerチャンネルがある場合はchannelIdを明示します。この教材の完成JSONは、名前を固定しないInspector割り当て方式のままです。シーク時のイベント配信と状態再構築の制約は、名前指定のonMouse方式でも同じです。<a href=\"/tutorials/feedback-sampling/\">Alternate：sample()とat()でFeedbackを描く</a>では、時刻から描き直す別の方法を紹介します。", { code: 'onMouseDown("Hand Take", e => {\n  console.log(e.x, e.y);\n}, { channelId: "pointer", space: "clip" });' })
], { level: "Feedback / Pointer callbacks", downloads: [{ href: "/projects/tutorials/feedback-pointer/practice-feedback.json", label: "練習用Feedback JSON" }] });

const pointerSampling = lesson("feedback-sampling", "Alternate：sample()とat()でFeedbackを描く", "Feedbackを名前で開き、現在時刻から光点と直近1.5秒の軌跡を描き直す。", "feedback-sample", [
  step("同じ記録を、別の方法で描く", '「<a href="/tutorials/feedback-pointer/">Feedbackで手の動きを録って再生する</a>」の別解です。ここではonMouseのイベントを蓄積せず、feedback()でアセットを名前で開き、sample()・at()で時刻に対応するデータを読みます。教材は1280 × 720、60 fps、8秒。同じHand Takeの2本の生成ストロークを使い、記録データは変更していません。開始用は光点のみ、完成版は直近1.5秒の軌跡も描きます。', { checks: ["目安20分。ブラウザEditor・アプリ版で編集でき、保存した結果はPlayerでも再生できます。", "同梱のHand Takeは練習用の生成データです。自分の記録は前の記事のRecord Feedback手順で用意できます。"] }),
  step("アセットを名前で選ぶ", "開始用を開き、TimelineのPointer Readerを選びます。CustomのtakeNameはHand Takeです。feedback(clip.takeName)はこの名前のProject内Feedbackアセットを開きます。参照は初回とtakeNameが変わったときだけ作り直し、同じ名前なら再利用します。自分の記録なら、Reviewで先にSaveし、takeNameを保存した名前へ変更してください。InspectorのSourceだけを変えても、コードが名前で選ぶアセットは変わりません。教材のSourceはEdit source…を開くための便宜的な設定で、PointerはNoneのまま使います。"),
  step("sample()で現在の光点を描く", "開始用のコードです。sample()は現在のClip時刻に対応するPointerの状態を読みます。feedback()で得た参照を使い回しても、sample()は呼ぶたびに現在時刻の値を読みます。同じアセットをReplaceした更新も読み取りに反映されます。space: clipは記録時のComposition座標をClipのCanvasへ換算します。x/yは座標、buttonsは押下中のボタン、insideは記録時にPointerが領域内にあったかです。Centiのbg()で毎フレーム消し、押下中は黄色、離した状態はピンクの光点を描きます。", { code: feedbackSampleCode }),
  step("at()で過去1.5秒の軌跡を描く", "完成版のコードです。onFrameのtimeから1.5秒さかのぼり、最大91点を1/60秒間隔で描きます。先頭付近で0秒を繰り返し読む処理を省き、現在の点はsample()の結果を再利用します。spaceのoptionsもループの外で共有します。buttonsとinsideが有効な区間だけをつなぐため、ボタンを離した区間をまたぐ線を作りません。フレームごとに背景から描き直し、線の点列を実行中の状態として蓄積しない構造です。", { code: feedbackCode }),
  step("sample()とat()の時間を区別する", "sample()はfeedback()に指定したoffset・rate・loopを使って現在時刻を写します。一方、at(channel, seconds)のsecondsは記録データ内の秒数です。このコードはoffset 0・rate 1・loop falseなので、Clipのtimeをそのままat()へ使えます。これらを変更する場合は、軌跡側の時間計算も合わせて変更してください。InspectorのTimingを変えても、この名前指定コードのoptionsは変わりません。", { table: table(["読み方", "使う時刻", "この教材での役割"], [["sample(\"pointer\")", "現在のClip時刻をoptionsで変換", "現在の光点"], ["at(\"pointer\", seconds)", "記録内の秒数を直接指定", "直近1.5秒の軌跡"], ["onMouseDown / Move / Up", "前進再生で通過したイベント", "別記事の蓄積型の描画"]]) }),
  step("シークして描き直しを確かめる", "完成版を停止し、フレーム120 → 300 → 120へシークして光点と軌跡を比べます。このClipは現在時刻から必要なデータを読み直すので、前の再生経路に依存せず同じ120の描画へ戻れます。onMouse方式では、シークだけで過去のイベントを再実行しない点が違います。光点を中心に見るなら開始用、軌跡も見るなら完成版を使い、完成版の1.5を変えて残す時間も試してください。"),
  step("自分のデータで保存する", "自分の記録に切り替える場合はCustomのtakeNameを変更します。PointerチャンネルのIDがpointer以外なら、sample()とat()の両方でIDも変更します。再生・停止・シークを確認し、File > Save Asで保存してください。Feedbackアセットとコードを含むプロジェクトとして開き直せます。イベントで状態を組み立てたい場合は前の記事、時刻から同じ結果を描き直したい場合はこの方法を選べます。")
], { level: "Feedback / Alternate", downloads: [{ href: "/projects/tutorials/feedback-pointer/practice-feedback.json", label: "練習用Feedback JSON" }] });

const feedbackEditor = lesson("feedback-editor", "Feedback Editorでストロークを直す", "0.3.18で加わった編集機能。ストロークを整え、適用・Undo・下書きの保存範囲を理解する。", "feedback-edit", [
  step("元データを残して編集を始める", "開始用JSONのHand Takeには、意図的に細かい揺れを加えた生成ストロークが2本あります。完成版は揺れを除いた比較用データです。自分の記録を使う場合も、元のプロジェクトを別名保存してから始めると比較しやすくなります。アプリ0.3.18のFeedback Editorを題材にしています。同じ編集画面はブラウザEditorにもありますが、アプリ側の検証記録とは別です。描画は前の記事と同じonMouse方式で、開始用・完成版ともInspectorのSource Hand Take・Pointer pointer・Space Clipを割り当て済みです。", { checks: ["先に「Feedbackで手の動きを録って再生する」を読むと、記録と描画の関係を確認できます。", "目安20〜30分。元の形を保ちたいときは、最初にAdd as newで別アセットにする方法を使います。"] }),
  step("Feedback Editorを開く", "ProjectのHand Takeを右クリックしてEdit…を選びます。適用済みSourceがあるClipではInspector > Feedback > Edit source…からも開けます。EditorドックがCodeからFeedbackへ切り替わり、Path・Strokes・TimelineとSettingsで記録を見られます。小さい場合はEditorを最大化してください。ここのローカルプレビューはClipコードを実行せず、入力イベントも送りません。"),
  step("ストロークと点を整える", "PathまたはStrokesで1本を選び、移動や時間の伸縮、点の位置編集を試します。選択するだけでは再生位置は動かないので、ローカルのルーラーやGo to strokeで確認します。Resampleは点の再配置をプレビューしてからApplyまたはCancelします。ボタンの複雑な押し替えなど編集非対応の記録は閲覧用になります。number・OSCなど他のチャンネルは保持されます。"),
  step("ローカルUndoで試行錯誤する", "Feedback Editor内のUndo / Redoは、まだプロジェクトへ適用していない編集履歴を戻します。点を動かしてUndoし、元に戻ることを確認してください。数値入力の下書きやResampleのプレビューが残っている場合は、確定またはキャンセルしてから保存へ進みます。これは次のAdd / Replaceを戻すプロジェクトUndoとは別の履歴です。"),
  step("Add as newとReplace originalを選ぶ", "Feedback EditorのSaveメニューから適用先を選びます。Addは元を残して比較したいとき、Replaceは同じ記録を使う参照全体へ変更を反映したいときに使います。どちらもプロジェクト側では1回のUndo操作になります。", { table: table(["操作", "アセットと参照", "その後にすること"], [["Add as new Feedback…", "新しいIDの別アセットを作る。既存の参照は元のまま", "ClipのSourceを追加アセットへ変更し、Pointerを選んでApply"], ["Replace original…", "確認後、同じIDの元アセットを置き換える", "同じSourceのまま新データを使う。0から再生して線を描き直す"], ["Export Feedback JSON…", "編集中の確定モデルをJSONへ出す。プロジェクトへは適用しない", "別ファイルとして保存し、必要なら後で読み込む"]]) }),
  step("下書きはメモリ上だけ、と覚える", "プロジェクトのSave / Save Asを押しても、Feedback Editorの未適用下書きは保存されません。保存されるのは適用済みデータで、下書きを含めなかった旨の案内が出ます。AddまたはReplaceを明示的に実行してから、さらにプロジェクトを保存してください。終了時の保護確認はクラッシュ復旧ではなく、強制終了するとメモリ上の下書きは失われます。", { checks: ["安全な順番：数値入力・Resampleを確定 → FeedbackのSaveでAdd / Replace → プロジェクトのSave As。", "Media exportでも未適用編集の扱いを選びます。編集中の見た目がそのまま書き出されるとは限りません。"] }),
  step("描画へ戻って適用を確かめる", "Codeへ戻り、TimelineのPointer Readerを選びます。Addを使った場合はInspector > FeedbackのSourceを追加したアセットへ変え、Pointerにpointer、SpaceにClipを選んでApplyします。Replaceなら同じSourceを使えます。以下は前の記事と同じコードで、takeNameやfeedback()は使いません。0へ戻ってPlayし、onMouseのイベントから線を描き直してください。Pause・シーク・フレームステップでは過去の線を再構築しません。必要ならプロジェクトUndoでAdd / Replaceを戻して比較し、再び0から再生します。最後に保存して開き直し、記録とPointer割り当てが残ることを確認します。", { code: pointerMouseCode })
], { level: "Feedback Editor / 0.3.18", downloads: [{ href: "/projects/tutorials/feedback-editor/practice-feedback.json", label: "練習用Feedback JSON" }] });

const shader = lesson("shader-chromatic", "初めてのShader：映像を色収差で加工する", "Effect layerの入力からRGBを分け、ずらす量をキーフレームで動かす。", "shader-workflow", [
  step("入力映像とEffectの役割を見る", "開始用は白い線と文字が動くSourceと、その映像をそのまま返すChromatic Shaderです。1280 × 720、60 fps、240フレームで、WebGL2が必要です。完成版ではRGBの輪郭がずれます。まず加工前のSourceを確認し、Effectを一時的に非表示にして比較してみましょう。", { checks: ["目安20分。HTML ClipのJavaScriptと、ShaderタブのGLSLは別の言語です。", "保存済みEffectはPlayerで再生できます。Player自体に作成・書き出し機能はありません。"] }),
  step("Effect layerへ入力を設定する", "自分で作る場合はComposition > New Shader Clipを選びます。RGB EffectのEffect layerを選択し、Input layersにSourceを指定します。教材はSelected Layer方式です。入力として消費されたSourceは最終出力へ重複描画されません。同じ入力を複数のSelected Layer Effectへ重ねて割り当てたり、循環する接続にはしないでください。"),
  step("Shaderタブへ色収差のコードを書く", "TimelineのChromaticを選び、Shaderタブを次のGLSLへ置き換えます。inputTextureは合成済み入力、vUvは左上原点のUVです。中央のG、少し離れた場所のRとBを組み合わせます。端のUVをclampし、透明度は中央の入力を保持しています。", { code: chromaticShader, codeLabel: "GLSL ES 1.00 / Shader", language: "glsl" }),
  step("amountをuniformへつなぐ", "Inspectorでnumberのamountを追加し、範囲0〜24、初期値0にします。教材では作成済みです。同名のuniform float amountへ値が入り、resolution.xで割ることで横方向のピクセル量をUVへ直します。amount 0は元の映像、14は横へ14ピクセルずらす設定です。uniformはコード内でも宣言が必要です。"),
  step("キーで一瞬だけ強くする", "amountを0フレームで0、60で14、120で0、180で20、239で0にしてキーを付けます。完成版はSine In Outです。加工量を常に大きくするより、タイトルの登場や切り替えの瞬間だけ強めると変化が読みやすくなります。Shader内のtimeはClipローカル時間ですが、この例の強度はキーが決めています。"),
  step("入力を入れ替え、エラーを確認する", "慣れたらSourceを自分の動画や別のClipに替えて同じ加工を試します。黒い・透明な結果になる場合はInput layers、EffectとSourceの有効範囲、WebGL2、コンパイルエラーを確認してください。Editorは直前の正常なShaderをstale表示で残す場合があります。保存前にエラーがない状態へ戻し、通常のEditorプレビューと書き出しで結果を確認します。")
], { level: "GLSL / Effect" });

const audio = lesson("audio-reactive", "音に反応するグラフィックをつくる", "low・mid・highの帯域を、円の大きさとバーの高さへ割り当てる。", "audio", [
  step("音の入ったTimelineを開く", "開始用には8秒のオリジナル合成音源Workshop Beatと、まだ音に反応しない3つの円があります。音源はWAVとしてJSONへ埋め込み済みです。完成プレビューは初期ミュートなので、音を聞くときだけSound offを切り替えてください。EditorでもTimelineへ音声Clipが配置されていることを確認します。", { checks: ["目安15〜20分。マイク入力ではなく、Projectに読み込んだ音声アセットを解析します。", "音を聞く操作と映像の解析は別です。ミュートでも帯域の可視化を確認できます。"] }),
  step("audioBand()の値を読む", "BandsのJavaScriptでaudioBand(\"Workshop Beat\", \"low\")を呼びます。アセット名はProject内で一意にします。戻り値は0〜1で、CompositionのPlayheadに従います。対象の音声Clipがそのフレームで有効でない場合は0です。単にProjectへ音源を読み込んだだけでは、Timeline上の解析対象にはなりません。"),
  step("3つの帯域を別の形へ割り当てる", "次の完成コードでBandsのJavaScriptを置き換えます。low・mid・highを3つの円とバーへ対応させ、gainで反応量を増やしています。音がないときも半径38の円が見えるようにし、解析値だけを描画の唯一の条件にはしません。", { code: audioCode }),
  step("gainと上限を調整する", "Customのgainを2から変え、反応の強さを比較します。min(1, ...)で描画用の値を制限しているため、強い音で円が無制限に大きくなりません。帯域ごとに別の係数へ変えてもかまいません。完成例は3色に分けていますが、色・回転・透明度へ割り当てることもできます。", { table: table(["帯域", "教材の割り当て", "変更してみる例"], [["low", "左の円とバー", "全体のscaleや背景の明るさ"], ["mid", "中央の円とバー", "線幅や回転量"], ["high", "右の円とバー", "小さな光点やアクセント色"]]) }),
  step("再生とシークで同期を確かめる", "再生中に円が動くことを確認し、停止して同じフレームへ戻ります。フレームごとの値は音声の解析結果とPlayheadから読みます。反応しないときは名前、有効な音声ClipのIn / Out、レイヤー表示、音源のデコードを確認してください。複数の同名アセットを作らないようにします。"),
  step("自分の音源へ差し替えて保存する", "自分で利用できる音源を読み込み、Timelineへ配置し、コードのWorkshop Beatをそのアセット名へ変えます。音源が変われば帯域の分布も変わるのでgainを調整します。完成プロジェクトを保存し、必要ならH.264やPNG連番へ出力します。ドラム・ベース・ボーカル単位で分けるには、帯域とは別のステム解析を使います。")
], { level: "Audio / Canvas", downloads: [{ href: "/projects/tutorials/audio-reactive/workshop-beat.wav", label: "教材のオリジナルWAV" }] });

const type = lesson("kinetic-type", "文字が主役のモーションをつくる", "1文字ずつの時間差、移動、透明度をひとつのrevealで制御する。", "defineparams", [
  step("動かないタイトルから始める", "開始用は中央にMOTIONと表示する4秒のClipです。完成版では文字が順番に上がって現れ、下線が伸び、終わりに消えます。Canvasへ文字を描くので、この教材はDOMだけのHTMLをキャプチャする方式に依存しません。ブラウザやOSのsans-serifを使うため、文字の形は環境で多少異なります。"),
  step("文字と演出を別のパラメータにする", "TitleのCustomにはtitle・reveal・tintがあります。titleは表示する文字列、revealは0〜1の進行、tintは色です。開始用のrevealは1なので文字が見えます。まずtitleをHELLOなど短い文字へ変え、コードを書き直さずに内容を変更できることを確認してください。", { checks: ["長い文字列はCanvasからはみ出します。まず6〜8文字程度で試し、フォントサイズやtrackingで構図を調整します。"] }),
  step("文字ごとに少しずつ遅らせる", "配列の番号iを使ってrevealから時間差を引きます。0.07が文字ごとの遅れ、0.55が各文字の登場に使う幅です。移動は三次の減速、透明度はuで変化させています。Array.from()で分けた文字をmeasureText()で測り、全体を中央へ配置します。固定フォントの文字幅と全幅はtitle変更時だけ計算し、revealによる移動と透明度は毎フレーム更新します。", { code: typographyCode }),
  step("revealへキーを付ける", "0フレームで0、90で1、180で1、239で0にします。90〜180を同じ値にすると、読める状態で止まる時間ができます。最後の1秒ほどで消える動きを作れます。完成版はLinearのキーで、各文字の動きにコード側の減速を加えています。キーの補間まで変えると、両方が重なって効きます。"),
  step("色と余白で読みやすくする", "tintを変えて背景との明暗差を見ます。文字が短くなっても中央に寄ること、下線と文字の間に余白があることを確認します。日本語なども試せますが、絵文字や結合文字を見た目の1文字へ完全に分割する処理ではありません。映像で読む時間を確保し、動きが止まる区間も作品の一部として設計します。"),
  step("シークして別の文言にも使う", "フレーム0・45・90・180・239へシークし、登場・静止・退場を確認します。文字の位置と透明度は現在のrevealから毎回計算するので、順番に再生しなくても確認できます。titleを変えて別名保存すれば、同じ演出を使い回せます。")
], { level: "Type / Parameters" });

const palette = lesson("shared-palette", "ひとつの操作で作品全体の色を変える", "Compositionのhueを、背景・文字・図形の3つのClipで共有する。", "comp", [
  step("色をそろえる3つのClipを見る", "開始用にはTitle + Background、Rings、Barsという3つのClipがあります。どれか1つのtintを直接変えるのではなく、Compositionのhueを参照して同じ配色ルールで描画します。hueは0〜360の数値で、もう1つの色はhue+60から作ります。完成版ではキーで全体の配色が変わります。"),
  step("Compositionのパラメータを選ぶ", "Clipの選択を外してComposition側のInspectorを開き、parametersのhueを探します。教材では作成済みです。自分で始める場合はCompositionのnumberパラメータとしてhueを追加し、初期値200、範囲0〜360にします。HTML ClipのCustomへ同じ名前を作る操作とは異なります。"),
  step("各Clipからcomp.hueを読む", "3つとも同じコードで、panelだけが0・1・2に分かれています。comp.hueは共有値、clip.panelはその配置の役割です。hueからCSSのhsl色を作り、パレットを個々のClipへコピーせずに使います。", { code: paletteCode }),
  step("1つの値で全部が変わることを確かめる", "hueを200、320、40と変えます。背景・文字・輪・バーが同時に変わることを確認してください。変わらないClipがあれば、clip.hueを読んでいないか、別のCompositionへ置いていないか確認します。この共有範囲は同じComposition内です。", { table: table(["値の場所", "読み方", "用途"], [["Composition", "comp.hue", "同じシーン全体のテーマ色"], ["Clip配置", "clip.panel", "その配置の役割や個別設定"]]) }),
  step("共有値にキーを付ける", "Compositionのhueへ、0フレームで200、120で320、239で200のキーを付けます。完成版はSine In Outです。色の文字列を補間するのではなくhueという数値を補間するので、途中の色相も通ります。359→1などの境界は数値として長い方向へ進むため、意図した経路か確認します。"),
  step("別の作品でも使える配色ルールにする", "色の変化を止めたい場合はCompositionのキーを外してhueを固定します。もう少し発展させるなら彩度や明るさも共有パラメータにし、Clip固有の役割は残します。保存した共有値とキーはPlayerにも渡るので、Editorで決めたテーマをWeb再生でも使えます。")
], { level: "Composition / Color" });

const camera = lesson("camera-work", "3Dのカメラワークだけで魅せる", "2台のCameraをTransformでつなぎ、低空の急接近・バンク・反転をつくる。", "3d-camera-switch", [
  step("カットだけのコースを再生する", "1280 × 720、60 fps、8秒のドローンレース風教材です。リング・柱・床グリッド・箱・球体はすべて静止しています。開始用にはCamera AとCamera Bの2アセットを交互に使う8個のTimeline配置があり、切り替えはすべてCutです。完成版は2台のカメラ間をTransformで補間して、低空への急接近、左右のスラローム、上昇からの反転をつなぎます。", { checks: ["目安20〜30分。「Timelineで3Dシーンをつくる」のTargetと配置の基本を先に確認してください。", "動きが激しい教材です。最初は停止してシークで構図を確認できます。プレビューカードはホバー中だけ再生します。"] }),
  step("2台のCameraと8個の配置を見分ける", "ProjectのCamera A / Camera Bはアセット、TimelineのCamera A / 01〜Camera B / 08は配置です。2アセットを複数回配置し、各配置のposition・rotation・FOVを個別に変えています。全カメラのTargetはScene1、ParentはNone、Camera TypeはPerspective、Aim ModeはRotationです。Aimへ切り替えると向きが自動で上書きされるため、この教材のバンクを保つにはRotationのまま使います。"),
  step("In / Outで次の構図を選ぶ", "Camera A / Bレイヤーの8配置は、それぞれ60フレームで隙間も重なりもありません。Outは含まれないため、フレーム59はA / 01、60からB / 02が選ばれます。Camera・Scene・親のNull・Mesh・Lightが同じ時刻に有効か確認してください。以下は配置済みの構図です。rotationとFOVはInspector表示の度で、JSON内部の角度はラジアンです。", { table: table(["In–Out / Camera", "position", "rotation（度）/ FOV"], cameraFlightShots.map((shot, i) => [`${i * 60}–${(i + 1) * 60} / ${i % 2 ? "B" : "A"}`, `[${shot.position.join(", ")}]`, `[${shot.rotation.join(", ")}] / ${shot.fov}`])) }),
  step("入ってくるCameraをTransformにする", "B / 02を選び、InspectorのTransitionをTransform、Durationを60にします。同じ設定をA / 03からB / 08までの7配置へ入れます。A / 01はCutのままです。60フレーム＝1秒で、直前のCameraの切り替え前フレームの姿勢から、選ばれたCameraの姿勢へ移ります。両端を明示したCameraにし、組み込みのデフォルトCameraへ切り替わる隙間を作らないでください。", { table: table(["Transition", "見える変化"], [["Cut", "切り替えフレームですぐ次の構図へ"], ["Dissolve", "2つの視点を描画し、映像を重ねてフェード"], ["Transform", "1台の仮想Cameraの位置・向きを補間し、空間を移動"]]) }),
  step("バンク・広角・短い補間で速度感を出す", "この完成版には位置やrotationのキーフレームがありません。各構図をつなぐTransformが移動を作ります。位置は直線、向きはQuaternionの球面補間、同じPerspective間のFOVも補間されます。進行はLinearで、Easing設定はありません。低い高さ、左右の傾き、80〜100度の広角、近くを通るリングと柱の視差で速度感を作ります。Durationを30〜45へ短くすると、移動がさらに速くなり、残り時間は次の構図で止まります。大きなバンクを含みますが、360度ロールの回転数を指定する機能ではありません。"),
  step("境界と途中をシークして保存する", "59・60・89・119・120・150・300・360・479へシークし、切り替え直前・補間の途中・到達点を比べます。Sceneの物体が動かず、Cameraだけが移ることを確認してください。補間は再生履歴に依存せず、同じフレームへ戻れば同じ構図になります。Transformの直線経路に衝突回避はないため、物体へ突っ込む場合は構図の位置・向きを変えます。最後の構図は最初と同じで、ループの境界を合わせています。File > Save Asで保存し、Playerでも再生して確認します。")
], { level: "3D / Camera Transform" });

const swarm = lesson("runtime-swarm", "add()でひとつのClipから群れをつくる", "ひとつのDotアセットを36個へ増やし、描画を共有して別々に動かす。", "add", [
  step("1個のDotから始める", "開始用では、Swarm ControllerがProjectのDotアセットをadd()で1個だけ配置します。Dotは80 × 80のHTML Clipで、Timelineに直接並べていません。完成版でもTimeline上のControllerは1つのままですが、実行時に36個のDisplay Objectが作られます。", { checks: ["目安20分。配列・for文・三角関数の基本が分かると進めやすい教材です。", "add()は2Dのホスト合成です。Three.jsのscene.add()やTimelineの3D Parentとは別の仕組みです。"] }),
  step("add()は最初に呼び、戻り値を残す", "Controllerのコード先頭でadd(\"Dot\", ...)を呼び、戻り値をmasterに保存します。アセット名はProject内で一意にします。anchorPoint [40, 40]はDotの中心です。onFrame()のたびにadd()を呼ぶと数が増え続けるため、生成と毎フレームの更新を分けます。ControllerのCanvasは透明にし、背景色は下のBackground Clipが担当します。Controller自身で不透明な背景を描くと、実行時の子を隠してしまうためです。"),
  step("instanceOfで描画を共有する", "残り35個はinstanceOf: masterを指定します。同じHTML Clipの描画を再利用し、位置・倍率・透明度を分けます。色などDotの中身そのものは共有するため、1個ずつ別の絵にしたい場合は通常のadd()で独立した描画を作る方法と比較してください。", { code: swarmCode }),
  step("配列番号から群れの動きをつくる", "dots.forEach()の番号iから位相と半径を分け、timeからx・yを計算します。dot.scaleとdot.opacityはホスト側の変形です。Controllerのspreadは群れ全体の広がりに掛けます。完成版はspreadを0で0.55、120で1.15、239で0.55にしてキーで広がりを動かしています。"),
  step("数と見た目の負荷を調整する", "36を12や24へ変え、動きと描画負荷を比較します。instanceOfを使っても合成するオブジェクト数は増えるため、無制限に増やさないようにします。画面外のものをvisible=falseにする、不要なオブジェクトをremove()する、といった管理もできます。手動でremove()した場合は配列側でも更新対象から外してください。"),
  step("シークと再読み込みで確かめる", "同じフレームへ戻って同じ配置になることを確認します。Display ObjectそのものはプロジェクトJSONへ保存されず、保存するのはアセットと生成コードです。開き直すとコードが群れを作り直します。この教材のControllerはIn 0に置き、Runtime childの時間の違いを避けて比較できるようにしています。")
], { level: "add() / Runtime" });

export const workshopLessons = [curve, pointer, pointerSampling, feedbackEditor, shader, audio, type, palette, camera, swarm];

const feedbackImage = (file, alt, caption) => ({ src: `/assets/tutorials/feedback-editor/${file}.jpg`, width: 3342, height: 2554, alt, caption });
feedbackEditor.steps[1].image = feedbackImage("01-workspace", "Feedback EditorでStroke 01と点のXを編集し、Undoと未適用の状態を表示した実画面", "実際のブラウザEditorで1点を編集した状態。下部のUnapplied editsは、まだプロジェクトへ適用していないことを示します。");
feedbackEditor.steps[4].image = feedbackImage("02-save-menu", "Feedback EditorのSaveメニューにAdd as new Feedback、Replace original、Export Feedback JSONを表示した実画面", "FeedbackのSaveで適用方法を選びます。プロジェクト全体のSaveとは別の操作です。");

export const workshopTranslations = {
  "curve-motion": { title: "Make the same motion feel better with Curve", summary: "Three circles share positions and duration. Change only interpolation to compare their feel.", steps: [
    step("Start with three identical motions", "The starter is 1280 × 720 at 60 fps for 240 frames. Every x track uses 230 at frame 0, 1080 at 119 and 230 at 239, initially with Linear easing. The completed preview compares Linear, Sine In Out and Back Out, top to bottom. Watch their starts and arrivals.", { checks: ["Allow 15–20 minutes. Familiarity with Inspector keyframes is enough.", "The code only draws x. Keep key times and values identical for a fair comparison."] }),
    step("Inspect the x keys", "Select SINE IN OUT on the Timeline, then Custom > x. Switch to Frames and seek to 0 / 119 / 239 to check values 230 / 1080 / 230. Do not add keys yet: separate the drawing code from the track that determines change over time."),
    step("Change interpolation in Curve", "Switch to Curve, select x's frame-0 key and choose Sine In Out under Easing. This controls 0→119. Do the same at 119 for the return to 239. The last key has no following interval inside this duration.", { checks: ["Selecting a key does not move the playhead. Seek with the ruler or Timeline position.", "Keep Frame and Value unchanged; first change only Easing."] }),
    step("Compare Linear, Sine and Back", "Set BACK OUT's keys at 0 and 119 to Back Out. It passes the destination before settling. Identical positions and duration can feel very different through acceleration, arrival and overshoot.", { table: table(["Easing", "What changes", "Useful for"], [["Linear", "Constant speed inside an interval", "Scanning and comparison baselines"], ["Sine In Out", "Slow starts and stops", "Calm movement and UI entrances"], ["Back Out", "Overshoot then return", "Elastic entrances and emphasis"]]) }),
    step("Shape an arrival with Bezier", "Select an interval's starting key, switch to Bezier and move its handles. Horizontal position relates to time within the interval; vertical position controls value change. Flattening the end reduces change before arrival. Compare with the completed project and Undo experiments. Overshoot may leave the image, so check actual drawing too."),
    step("Compare still frames and save", "Seek to 0 / 30 / 60 / 90 / 119. Intermediate positions differ while the endpoints match. Out 240 is excluded. Try changes to timing separately from easing, then use File > Save As.")
  ] },
  "feedback-pointer": { title: "Record and replay hand motion with Feedback", summary: "Assign Pointer in the Inspector and receive recorded strokes through onMouseDown, Move and Up.", downloads: [{ href: "/projects/tutorials/feedback-pointer/practice-feedback.json", label: "Practice Feedback JSON" }], steps: [
    step("Compare the starter and completed project", "This study is 1280 × 720, 60 fps and eight seconds. It receives the Inspector-assigned recording through onMouseDown(), onMouseMove() and onMouseUp(). Hand Take contains two generated practice strokes, rather than an actual hand recording. The starter has Pointer None, while the completed version assigns pointer. Code and recording data are shared. Open the completed preview and press Play to watch strokes and event counts grow. Feedback stores coordinates, button state and time, rather than an image trail.", { checks: ["Allow 20 minutes. Record and assign data in either the browser Editor or app.", "The Player replays saved recordings. Use Play in the opened preview, not only the card's still image."] }),
    step("Record your own Pointer", "Open the starter, return to frame 0 and select Pointer in the Composition's Record Feedback settings, then start Record. Capture uses forward playback at 1× without looping. Press and draw in the preview, release, then draw another stroke. After Stop, choose Save in Review and add the asset under a name such as Hand Take 2. Discard drops that take. Recording uses Composition coordinates without preview zoom or pan. To practice assignment with the included data, skip recording and continue."),
    step("Set Source and Pointer in the Inspector", "Select Pointer Reader on the Timeline and open Inspector > Feedback. Set Source Hand Take, Pointer pointer and Space Clip. For your own recording, choose its new asset name instead. Under Timing and details, use Offset 0, Rate 1 and Loop OFF, then press Apply. Selecting Source while leaving Pointer None does not activate the unnamed onMouse callbacks. Check Standard input ready after applying and then play. You do not need to edit a Custom takeName parameter.", { table: table(["Setting", "Study value", "Purpose"], [["Source", "Hand Take, or your own recording", "Feedback asset to receive"], ["Pointer", "pointer", "Pointer channel to receive"], ["Space", "Clip", "Map recorded coordinates to the Clip canvas"], ["Offset / Rate / Loop", "0 / 1 / OFF", "Replay the original timing"], ["Apply", "Press after changes", "Save the assignment on the Clip"]]) }),
    step("Receive events in three callbacks", "onMouseDown(e => …) receives recorded presses, onMouseMove(e => …) receives recorded movement and onMouseUp(e => …) receives recorded releases. The following is a short diagnostic example. Register once at Clip top-level or in setup(), never in onFrame(). Without an asset-name argument, callbacks use the saved Inspector assignment. These functions replay recorded Pointer data; they do not monitor the live mouse over the preview. Callbacks run before onFrame() in the same frame, so you can collect points first and draw the resulting state.", { table: table(["Event value", "Meaning"], [["x / y", "Current coordinates in the assigned Space"], ["px / py", "Previous recorded event coordinates, not the previous rendered frame"], ["buttons / button", "Held-button bitmask / button that changed"], ["time / frameTime", "Feedback-local seconds / Clip-local seconds"], ["seq", "Recorded event order"], ["canceled", "True when a real cancel is delivered as onMouseUp"]]) }),
    step("Build lines from recorded events", "This is Pointer Reader's completed code. Down creates a stroke, Move appends points while a button is held, and Up ends it. bg(), lines(), oval() and text() are Centi drawing functions. The down/move/up numbers count callbacks actually delivered. The first tick samples state without handlers, so Move can also start a line when playback begins with the recorded button already held, using px/py as its first point. A canceled Up ends the current stroke without adding its final point."),
    step("Compare Play with seeking", "Play forward from 0 to deliver each event once and grow strokes and counts. Pause, frame step and seek dispatch no callbacks and do not replay earlier events. Seeking to a later time therefore does not rebuild its full trail. This code clears accumulated strokes when time moves backward. In the site's preview, Reset reloads the Clip; in the Editor, return to 0 and play forward. A forward seek retains earlier drawing state, so replay from the beginning when comparing the same stroke.", { checks: ["Move and other counts grow while playing and stay still while paused.", "Set Pointer None and Apply: the same code no longer receives recorded events.", "For repeatable images at arbitrary times, see Alternate: draw Feedback with sample() and at()."] }),
    step("Switch to your own recording and save", "Choose your saved Feedback as Inspector Source, select its Pointer channel and Apply. The same onMouse code now draws another hand movement. If nothing draws, check Source, Pointer, whether Apply was pressed, forward playback and the Clip's In/Out range. Save any take still in Review first, then File > Save As after assignment. Reopen and check that the recording asset and Pointer assignment remain. Accumulated lines are runtime state, so play again to redraw them after reopening."),
    step("Recognize the named-asset alternative", "An alternative form takes the Project asset name as an argument, such as onMouseDown(\"Hand Take\", callback). That form uses the named Feedback without an Inspector Pointer assignment. The following example uses Hand Take. Supply channelId when there are several Pointer channels. This tutorial's completed JSON keeps the Inspector-assignment form without a fixed asset name. The named onMouse form has the same event-delivery and state-reconstruction limits on seeking. <a href=\"/en/tutorials/feedback-sampling/\">Alternate: draw Feedback with sample() and at()</a> presents a method that redraws from time.")
  ] },
  "feedback-sampling": { title: "Alternate: draw Feedback with sample() and at()", summary: "Open Feedback by name and redraw a dot and the last 1.5 seconds of its trail from time.", downloads: [{ href: "/projects/tutorials/feedback-pointer/practice-feedback.json", label: "Practice Feedback JSON" }], steps: [
    step("Draw the same recording another way", 'This is an alternative to <a href="/en/tutorials/feedback-pointer/">Record and replay hand motion with Feedback</a>. Instead of accumulating onMouse events, open the asset by name with feedback() and read timed data with sample() and at(). The 1280 × 720, 60 fps, eight-second study keeps the same two generated Hand Take strokes unchanged. The starter draws only a dot; the completed version also draws a trail covering the last 1.5 seconds.', { checks: ["Allow 20 minutes. Edit in the browser Editor or app; replay saved results in the Player.", "Hand Take is generated practice data. Follow the previous article’s Record Feedback steps to capture your own movement."] }),
    step("Select an asset by name", "Open the starter and select Pointer Reader on the Timeline. Custom > takeName is Hand Take. feedback(clip.takeName) opens the Project Feedback asset with this name. Create the reader initially and only when takeName changes; reuse it while the name stays the same. For your own take, Save it from Review first and set takeName to the saved name. Changing Inspector Source alone does not redirect this explicit name reference. The supplied Source assignment is a convenience for Edit source…; leave Pointer None."),
    step("Draw the current dot with sample()", "This is the starter code. sample() reads Pointer state at the current Clip time. Reusing the feedback() reader does not freeze its values: each sample() reads current time, and replacements of the same asset remain visible. space: clip scales recorded Composition coordinates to the Clip canvas. x/y are coordinates, buttons reports held buttons and inside reports whether the recorded Pointer was in the region. Clear each frame with Centi bg(), then draw a yellow dot while held or a pink dot when released."),
    step("Draw a 1.5-second trail with at()", "This is the completed code. Draw up to 91 points at 1/60-second intervals over the 1.5 seconds before onFrame time. Avoid repeated reads of time zero near the start, reuse sample() for the current endpoint, and share the space options outside the loop. Connect only points with buttons and inside active, avoiding lines across released sections. Redraw from the background each frame instead of accumulating stroke points as runtime state."),
    step("Distinguish sample() time from at() time", "sample() maps current time using feedback() options offset, rate and loop. The seconds argument of at(channel, seconds) is recording-local time. This code uses offset 0, rate 1 and loop false, so Clip time can be passed directly to at(). If those options change, update the trail’s time calculation too. Changing Inspector Timing does not alter the options in this named-reference code.", { table: table(["Read", "Time", "Role in this study"], [["sample(\"pointer\")", "Current Clip time mapped through options", "Current dot"], ["at(\"pointer\", seconds)", "Explicit recording-local seconds", "Last 1.5 seconds of trail"], ["onMouseDown / Move / Up", "Events crossed during forward playback", "Accumulated drawing in the other article"]]) }),
    step("Verify redraws while seeking", "Pause the completed version and seek to frame 120 → 300 → 120. Compare the dot and trail. This Clip rereads the required data from current time, so returning to 120 redraws the same result independently of the earlier playback path. The onMouse version does not replay historical events on seek. Use the starter for the dot alone, or the completed version for the trail; change 1.5 in its code to adjust the trail duration."),
    step("Save with your own data", "To use your own recording, change Custom > takeName. If its Pointer channel ID differs from pointer, update the ID in both sample() and at(). Check Play, Pause and Seek, then File > Save As. Reopen the project with its recording asset and code. Use the previous article to build state from events, or this method to redraw the same result directly from time.")
  ] },
  "feedback-editor": { title: "Repair strokes in the Feedback Editor", summary: "Explore the 0.3.18 editing feature: refine strokes, apply changes, use Undo and understand memory-only drafts.", downloads: [{ href: "/projects/tutorials/feedback-editor/practice-feedback.json", label: "Practice Feedback JSON" }], steps: [
    step("Keep an original for comparison", "Hand Take in the starter contains two generated strokes with deliberate jitter; the completed data removes that jitter for comparison. With your own take, save a separate project first. This lesson covers the app's Feedback Editor introduced in 0.3.18. The browser Editor has the same screen, separate from the app's validation record. Drawing uses the previous article's onMouse code; both starter and completed projects already assign Inspector Source Hand Take, Pointer pointer and Space Clip.", { checks: ["Read the Pointer recording lesson first to connect capture and drawing.", "Allow 20–30 minutes. Use Add as new first when preserving the original matters."] }),
    step("Open the Feedback Editor", "Right-click Hand Take in Project and choose Edit…, or use Inspector > Feedback > Edit source… for an applied source. The Editor dock switches from Code to Feedback, with Path, Strokes, Timeline and Settings. Maximize it if needed. Local preview runs neither Clip code nor recorded input events."),
    step("Refine strokes and points", "Select a stroke in Path or Strokes and try moving it, stretching its timing or editing points. Selection does not seek: use the local ruler or Go to stroke. Resample previews point redistribution before Apply or Cancel. Unsupported complex button sequences are view-only; number, OSC and other channels are retained."),
    step("Experiment with local Undo", "Undo / Redo inside Feedback Editor restores its unapplied editing history. Move a point, then Undo. Resolve numeric drafts and Apply or Cancel any Resample preview before saving. This history is separate from project Undo for Add / Replace."),
    step("Choose Add as new or Replace original", "Choose an application mode from Feedback Editor's Save menu. Add preserves the source for comparison; Replace updates all references to the same asset. Each is one project Undo step.", { table: table(["Action", "Asset and references", "Next step"], [["Add as new Feedback…", "Creates a new asset ID; existing references stay on the original", "Set Clip Source to the new asset, select Pointer and Apply"], ["Replace original…", "Replaces data at the same ID after confirmation", "Keep the same Source; replay from 0 to redraw with new data"], ["Export Feedback JSON…", "Exports the current committed editing model without applying it to the project", "Save a separate file and import it later if needed"]]) }),
    step("Remember that drafts live only in memory", "Project Save / Save As excludes unapplied Feedback drafts and reports that applied data was saved instead. Explicitly Add or Replace first, then save the project. Exit protection is not crash recovery: a forced exit loses memory-only drafts.", { checks: ["Safe order: resolve numeric and Resample drafts → Feedback Save Add / Replace → project Save As.", "Media export also asks how to handle unapplied edits; the editing preview is not automatically the exported data."] }),
    step("Return to drawing and verify application", "Return to Code and select Pointer Reader on the Timeline. After Add, set Inspector > Feedback Source to the added asset, choose Pointer pointer and Space Clip, then Apply. Replace keeps the same Source. The following code matches the previous article and uses neither takeName nor feedback(). Return to 0 and Play to redraw strokes from onMouse events. Pause, seek and frame step do not reconstruct earlier strokes. Compare project Undo for Add / Replace if needed, replaying from 0 each time, then save and reopen to verify both data and Pointer assignment.")
  ] },
  "shader-chromatic": { title: "Your first Shader: chromatic aberration", summary: "Separate RGB samples from an Effect layer input and animate their offset with keys.", steps: [
    step("Identify the input and Effect", "The starter contains an animated Source of white lines and text, plus a pass-through Chromatic Shader. It is 1280 × 720 at 60 fps for 240 frames and needs WebGL2. The completed version separates RGB edges. Temporarily hide the Effect to compare.", { checks: ["Allow 20 minutes. HTML Clip JavaScript and Shader-tab GLSL are different languages.", "Saved effects play in the Player, which has no authoring or export controls."] }),
    step("Assign input to the Effect layer", "For a new setup use Composition > New Shader Clip. Select RGB Effect and assign Source under Input layers. The study uses Selected Layer mode: consumed inputs are not drawn again at the top level. Do not assign one input to several Selected Layer Effects or create cycles."),
    step("Write the Shader", "Select Chromatic on the Timeline and replace its Shader-tab source with this GLSL. inputTexture is the composited input and vUv starts at the upper-left. Combine center G with displaced R and B. Clamp edge UVs and preserve center alpha."),
    step("Connect amount to a uniform", "Add a number parameter amount with range 0–24 and initial value 0 in the Inspector; the study already has it. The matching float uniform receives its value. Dividing by resolution.x converts horizontal pixels to UV units. Zero preserves the image; 14 offsets samples by 14 pixels. Declare the uniform in GLSL too."),
    step("Animate a brief accent", "Key amount at 0:0, 60:14, 120:0, 180:20 and 239:0. The completed project uses Sine In Out. Brief stronger accents can emphasize a title or cut. Here keys determine strength rather than the Shader's Clip-local time uniform."),
    step("Swap inputs and check failures", "Try your own video or Clip as Source. For black or transparent results, check Input layers, active ranges, WebGL2 and compile errors. The Editor may show its last valid shader as stale. Restore an error-free state and check the regular Editor preview and export before saving.")
  ] },
  "audio-reactive": { title: "Make graphics respond to sound", summary: "Map low, mid and high bands to circle sizes and bar heights.", downloads: [{ href: "/projects/tutorials/audio-reactive/workshop-beat.wav", label: "Original workshop WAV" }], steps: [
    step("Open a Timeline containing audio", "The starter includes an eight-second original synthetic Workshop Beat and three circles that do not yet react. Its WAV is embedded. The completed preview starts muted; toggle Sound off only when you want to listen. Confirm an audio Clip is placed on the Editor Timeline.", { checks: ["Allow 15–20 minutes. This analyzes a Project audio asset, not microphone input.", "Listening and analysis are separate: muted playback still supports visualization."] }),
    step("Read audioBand()", "In Bands JavaScript, call audioBand(\"Workshop Beat\", \"low\"). Keep the Project asset name unique. The 0–1 value follows the Composition playhead and is zero outside an active matching audio placement. Merely importing the asset without placing it is not enough."),
    step("Map bands to separate shapes", "Replace Bands JavaScript with the completed code. It assigns low, mid and high to three circles and bars, with gain increasing the response. A base radius of 38 keeps circles visible even in silence."),
    step("Tune gain and limits", "Change gain from 2 and compare sensitivity. min(1, ...) bounds drawing size on loud input. Try separate gains per band or map energy to color, rotation and opacity.", { table: table(["Band", "Study mapping", "Try instead"], [["low", "Left circle and bar", "Overall scale or background brightness"], ["mid", "Center circle and bar", "Line width or rotation"], ["high", "Right circle and bar", "Small lights or accent colors"]]) }),
    step("Verify playback and seeking", "Play, pause and revisit a frame. Values come from decoded analysis and the playhead. For no response, check the name, audio range, layer visibility and decoding. Avoid duplicate asset names."),
    step("Replace the audio and save", "Import audio you may use, place it and replace Workshop Beat in code with its asset name. Retune gain for its frequency distribution. Save and optionally export H.264 or PNG sequences. Instrument stems use a separate analysis workflow from frequency bands.")
  ] },
  "kinetic-type": { title: "Make type the main motion", summary: "Drive staggered letters, movement and opacity with one reveal parameter.", steps: [
    step("Begin with a still title", "The four-second starter displays MOTION. The completed version raises letters in sequence, extends an underline, then exits. Text is drawn on Canvas, avoiding reliance on DOM-only HTML capture. It uses the system sans-serif, whose appearance may vary across browsers and operating systems."),
    step("Separate content and motion controls", "Title exposes title, reveal and tint. The starter has reveal 1 so text is visible. Change title to a short word such as HELLO and edit content without changing code.", { checks: ["Long text can leave the canvas. Begin with about 6–8 letters and adjust font size or tracking."] }),
    step("Stagger letters", "Subtract an index-based delay from reveal: 0.07 separates letters and 0.55 is each entrance's span. Movement uses cubic deceleration while opacity uses u. Array.from() splits the text and measureText() centers the measured letters. Cache widths and total width until title changes for this fixed font; reveal still updates motion and opacity every frame."),
    step("Key reveal", "Use reveal 0 at frame 0, 1 at 90, 1 at 180 and 0 at 239. Equal values at 90 and 180 create a reading hold. The completed keys are Linear; code adds per-letter deceleration. Easing the keys too combines both effects."),
    step("Check color and spacing", "Adjust tint for contrast. Check centering with shorter words and the underline's spacing. Array.from() does not fully segment combined characters or emoji into visual letters. Preserve a readable hold as part of the motion design."),
    step("Seek and reuse", "Seek to 0 / 45 / 90 / 180 / 239 to check entrance, hold and exit. Each frame derives positions and opacity from current reveal. Change title and save a variant to reuse the motion.")
  ] },
  "shared-palette": { title: "Recolor the whole piece with one control", summary: "Share a Composition hue across background, type and shapes in three Clips.", steps: [
    step("Inspect three coordinated Clips", "Title + Background, Rings and Bars all read Composition hue rather than separate tints. hue ranges from 0 to 360, with a second color at hue+60. The completed version animates the shared value."),
    step("Select the Composition parameter", "Deselect Clips to show Composition controls and find hue under parameters. It already exists in the study. For a fresh setup create a Composition number parameter hue, initial 200 and range 0–360. This differs from creating a Clip Custom value."),
    step("Read comp.hue in each Clip", "The Clips share code, with panel 0 / 1 / 2 identifying their roles. comp.hue is shared while clip.panel belongs to one placement. Build CSS hsl colors from hue rather than copying palettes into each Clip."),
    step("Change everything with one value", "Try hue 200 / 320 / 40 and check background, type, rings and bars. If one does not change, check for clip.hue or another Composition. Sharing is scoped to the same Composition.", { table: table(["Scope", "Read", "Purpose"], [["Composition", "comp.hue", "Theme color for the scene"], ["Clip placement", "clip.panel", "An individual role or setting"]]) }),
    step("Animate the shared value", "Key hue at 0:200, 120:320 and 239:200; the completed project uses Sine In Out. This interpolates a number through intermediate hues. Crossing 359→1 takes the numeric path, so check whether it is the direction you intend."),
    step("Keep a reusable palette rule", "Remove Composition keys to fix a theme. Later expose saturation and brightness too, retaining each Clip's role. Saved shared values and keys reach the Player as well.")
  ] },
  "camera-work": { title: "Let 3D camera movement tell the story", summary: "Use Transform between two Cameras for low passes, banks and a fast turnaround.", steps: [
    step("Play the cut-only course", "This drone-racing-style study is 1280 × 720, 60 fps and eight seconds long. Rings, posts, floor grid, box and sphere stay still. The starter alternates two Camera assets, A and B, across eight Timeline placements, all using Cut. The completed version uses Transform between Cameras for a low approach, left/right slalom, climb and turnaround.", { checks: ["Allow 20–30 minutes. Review Target and placement basics in the 3D Timeline tutorial first.", "This study has intense movement. Pause and seek to inspect compositions first. The preview card plays only while hovered."] }),
    step("Distinguish two assets from eight placements", "Camera A and Camera B in Project are assets; Camera A / 01 through Camera B / 08 on the Timeline are placements. Reuse the two assets, overriding position, rotation and FOV per placement. Every Camera targets Scene1, has Parent None, uses Perspective and Aim Mode Rotation. Aim would override orientation, so retain Rotation to preserve the bank."),
    step("Select compositions with In and Out", "The eight placements on Camera A / B each occupy 60 frames with no gaps or overlaps. Out is excluded: A / 01 is selected at 59 and B / 02 at 60. Keep Cameras, Scene, Mesh ancestors and Light active at the relevant times. These compositions are already prepared. Inspector rotation and FOV use degrees; project files store angles in radians.", { table: table(["In–Out / Camera", "position", "rotation (degrees) / FOV"], cameraFlightShots.map((shot, i) => [`${i * 60}–${(i + 1) * 60} / ${i % 2 ? "B" : "A"}`, `[${shot.position.join(", ")}]`, `[${shot.rotation.join(", ")}] / ${shot.fov}`])) }),
    step("Set the incoming Camera to Transform", "Select B / 02 and set Inspector Transition to Transform, Duration 60. Repeat for all seven incoming placements, A / 03 through B / 08. Leave A / 01 on Cut. Over 60 frames, or one second, the view moves from the outgoing Camera's pose on the preceding frame to the selected Camera's pose. Use explicit Cameras at both ends and avoid gaps that select the built-in default Camera.", { table: table(["Transition", "Visible result"], [["Cut", "Switch immediately to the next composition"], ["Dissolve", "Render two views and crossfade their images"], ["Transform", "Interpolate one virtual Camera's position and orientation through space"]]) }),
    step("Build speed with banks, wide lenses and short transitions", "The completed project has no position or rotation keyframes: Transform between prepared compositions creates the motion. Position interpolates linearly, orientation uses quaternion spherical interpolation and matching Perspective Cameras also interpolate FOV. Progress is Linear with no Easing control. Low altitude, banks, 80–100 degree FOV and nearby rings and posts create strong parallax. Try Duration 30–45 for faster travel followed by a hold at the incoming composition. Large banks are included, but this is not a control for a specified number of full 360-degree rolls."),
    step("Seek across boundaries and save", "Inspect 59, 60, 89, 119, 120, 150, 300, 360 and 479 for the preceding view, transition and destination. Only the Camera moves. Evaluation does not depend on playback history, so revisiting a frame gives the same composition. Transform has no collision avoidance along its straight path; adjust poses if it enters an object. The final pose matches the first for looping. Save As and check playback in the Player too.")
  ] },
  "runtime-swarm": { title: "Build a swarm from one Clip with add()", summary: "Turn one Dot asset into 36 objects, sharing drawing while moving them independently.", steps: [
    step("Start with one Dot", "Swarm Controller uses add() to place the Project Dot asset once. Dot is an 80 × 80 HTML Clip, not placed directly on the Timeline. The completed project still has one Controller placement but creates 36 runtime Display Objects.", { checks: ["Allow 20 minutes. Arrays, for loops and basic trigonometry help.", "add() controls 2D host compositing, separate from Three.js scene.add() and Timeline 3D parenting."] }),
    step("Create once and retain the object", "Call add(\"Dot\", ...) at initialization and keep master. Asset names must be unique. anchorPoint [40, 40] is Dot's center. Calling add() every onFrame creates ever more objects: separate creation from updates. Keep the Controller canvas transparent and draw color in the lower Background Clip; an opaque Controller can cover runtime children."),
    step("Share drawing with instanceOf", "Use instanceOf: master for the other 35 objects. They reuse an HTML drawing with separate transforms and opacity. Pixel content is shared; use independent add() drawing if each needs a different image."),
    step("Derive movement from indices", "Use each dots.forEach() index to vary phase and radius, calculating x/y from time. dot.scale and opacity are host transforms. Controller spread expands the group. The completed track uses 0:0.55, 120:1.15 and 239:0.55."),
    step("Tune object count and cost", "Try 12 or 24 instead of 36. instanceOf still adds compositing work per object. Hide offscreen objects with visible=false or remove unneeded ones. After remove(), exclude them from your update array too."),
    step("Seek and reopen", "Revisit a frame and compare positions. Runtime Display Objects are not serialized: the project saves assets and creation code, which recreates the swarm on open. This Controller starts at In 0 to make runtime-child timing easier to compare.")
  ] }
};

workshopTranslations["feedback-editor"].steps[1].image = feedbackImage("01-workspace", "Actual Feedback Editor with Stroke 01, a modified point X value, Undo and unapplied edits", "A point edited in the browser Editor. Unapplied edits means the draft has not yet been applied to the project.");
workshopTranslations["feedback-editor"].steps[4].image = feedbackImage("02-save-menu", "Actual Feedback Editor Save menu with Add as new Feedback, Replace original and Export Feedback JSON", "Choose an application mode from Feedback Save, separately from saving the whole project.");

const cameraImage = (alt, caption) => ({ src: "/assets/tutorials/camera-work/01-transform.jpg", width: 3342, height: 2554, alt, caption });
camera.steps[3].image = cameraImage("実EditorでCamera B / 02を選択し、Transition TransformとDuration 60、8つの配置を表示", "完成版を実ブラウザEditorで開き、89フレームへシークした状態。入ってくるCamera B / 02のTransitionを設定します。");
workshopTranslations["camera-work"].steps[3].image = cameraImage("Actual Editor with Camera B / 02 selected, Transition Transform, Duration 60 and eight placements", "The completed project in the actual browser Editor, paused at frame 89. Set Transition on the incoming Camera B / 02.");
